import { expect, type Page, test } from '@playwright/test';
import type { AngularRenderer } from '@storybook/angular-vite';
import type { PreviewWeb } from 'storybook/preview-api';

// Generated by `pnpm storybook:build`.
import storybook from '../storybook-static/index.json' with { type: 'json' };

// Only run tests on stories, not other documentation pages.
const stories = Object.values(storybook.entries).filter(
  (entry) => entry.type === 'story' && !entry.tags?.includes('skip-playwright'),
);

for (const story of stories) {
  test(`${story.title} ${story.name} should not have visual regressions`, async ({ page }) => {
    const parameters = new URLSearchParams({
      id: story.id,
      viewMode: 'story',
    });

    await page.goto(`/iframe.html?${parameters.toString()}`);
    await waitForPageReady(page);

    await expect(page).toHaveScreenshot(`${story.id}.png`, { fullPage: true });
  });
}

async function waitForPageReady(page: Page) {
  // await page.waitForLoadState('domcontentloaded');
  // await page.waitForLoadState('load');
  // await page.waitForLoadState('networkidle');
  // await page.evaluate(() => document.fonts.ready);

  // Optimisation: Storybook's `finished` render phase replaces the waits above and skips the 500 ms
  // `networkidle` quiet period on every story. `__STORYBOOK_PREVIEW__` is undocumented, so restore the
  // waits above if a Storybook upgrade breaks it.
  await page.waitForFunction(() => {
    const render = (globalThis as StorybookGlobal).__STORYBOOK_PREVIEW__?.currentRender;
    const phase = render && 'phase' in render ? render.phase : undefined;
    return phase === 'finished' || phase === 'errored' || phase === 'aborted';
  });
}

type StorybookGlobal = typeof globalThis & {
  __STORYBOOK_PREVIEW__?: PreviewWeb<AngularRenderer>;
};
